const test = require("node:test");
const assert = require("node:assert/strict");
const {
  msUntilNext,
  runDailyTelematicsBatch,
} = require("../FEAT-007-EXT-virtual-telematics/06-cron/dailyTelematicsScheduler");

// ── msUntilNext ──────────────────────────────────────────────────────────

test("msUntilNext: saat henuz gelmediyse bugune kurar", () => {
  const now = new Date("2026-10-11T01:00:00");
  const ms = msUntilNext(2, 0, now);
  assert.equal(ms, 60 * 60 * 1000); // 1 saat sonra
});

test("msUntilNext: saat gectiyse ertesi gune kurar", () => {
  const now = new Date("2026-10-11T03:00:00");
  const ms = msUntilNext(2, 0, now);
  assert.equal(ms, 23 * 60 * 60 * 1000); // yarin 02:00'a 23 saat
});

test("msUntilNext: tam o saatteyse (esit) ertesi gune kurar, 0/negatif donmez", () => {
  const now = new Date("2026-10-11T02:00:00");
  const ms = msUntilNext(2, 0, now);
  assert.equal(ms, 24 * 60 * 60 * 1000);
  assert.ok(ms > 0);
});

test("msUntilNext: ay sinirini dogru gecer (31 Ekim 02:00 -> 1 Kasim 02:00)", () => {
  const now = new Date("2026-10-31T02:00:01");
  const ms = msUntilNext(2, 0, now);
  assert.equal(ms, 24 * 60 * 60 * 1000 - 1000);
});

// ── runDailyTelematicsBatch ──────────────────────────────────────────────

function fakeFastify(queryImpl) {
  const logs = { info: [], error: [] };
  return {
    pg: {
      async connect() {
        return {
          query: queryImpl,
          released: false,
          release() {
            this.released = true;
          },
        };
      },
    },
    log: {
      info: (obj, msg) => logs.info.push({ obj, msg }),
      error: (obj, msg) => logs.error.push({ obj, msg }),
    },
    _logs: logs,
  };
}

test("runDailyTelematicsBatch: uc batch'i de sirayla calistirir, hepsi basariliysa outcome'da processed doner", async () => {
  const fastify = fakeFastify(async (sql) => {
    if (sql.includes("FROM public.fuel_records")) return { rows: [] };
    if (sql.includes("esp32_device_id IS NOT NULL")) return { rows: [] };
    if (sql.includes("DISTINCT d.company_id")) return { rows: [] };
    if (sql.trim() === "BEGIN;" || sql.trim() === "COMMIT;") return {};
    throw new Error("unexpected sql: " + sql);
  });

  const outcome = await runDailyTelematicsBatch(fastify);

  assert.equal(outcome.fuel.processed, 0);
  assert.equal(outcome.reconcile.processed, 0);
  assert.equal(outcome.correlation.processed, 0);
  assert.equal(fastify._logs.error.length, 0);
});

test("runDailyTelematicsBatch: fuelSnapshotBatch patlarsa diger ikisi yine de calisir, client her zaman release edilir", async () => {
  let released = false;
  const fastify = {
    pg: {
      async connect() {
        return {
          query: async (sql) => {
            if (sql.includes("FROM public.fuel_records"))
              throw new Error("fuel patladi");
            if (sql.includes("esp32_device_id IS NOT NULL"))
              return { rows: [] };
            if (sql.includes("DISTINCT d.company_id")) return { rows: [] };
            if (sql.trim() === "BEGIN;" || sql.trim() === "COMMIT;") return {};
            throw new Error("unexpected sql: " + sql);
          },
          release() {
            released = true;
          },
        };
      },
    },
    log: { info() {}, error() {} },
  };

  const outcome = await runDailyTelematicsBatch(fastify);

  assert.equal(outcome.fuel.error, true);
  assert.match(outcome.fuel.message, /fuel patladi/);
  // digerleri yine de calisti (fuel'in hatasi onlari durdurmadi)
  assert.equal(outcome.reconcile.processed, 0);
  assert.equal(outcome.correlation.processed, 0);
  assert.equal(released, true);
});

test("runDailyTelematicsBatch: connect() basarisiz olursa hata yukari firlatilir (zamanlayici bunu loglar)", async () => {
  const fastify = {
    pg: {
      async connect() {
        throw new Error("DB baglanamadi");
      },
    },
    log: { info() {}, error() {} },
  };

  await assert.rejects(
    () => runDailyTelematicsBatch(fastify),
    /DB baglanamadi/
  );
});
